 public boolean permission(int q,int[] results){if(q!=91)return false;if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)open();else fail(a.getString(R.string.capture_denied));return true;}
 private void open(){try{discard();File dir=new File(a.getFilesDir(),"captures");if(!dir.exists()&&!dir.mkdirs())throw new IOException();name="capture-"+UUID.randomUUID()+(video?".mp4":".jpg");if(!file().createNewFile())throw new IOException();output=uri();Intent i=new Intent(video?MediaStore.ACTION_VIDEO_CAPTURE:MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,output);i.setClipData(ClipData.newRawUri("capture",output));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if(video){i.putExtra(MediaStore.EXTRA_DURATION_LIMIT,60);i.putExtra(MediaStore.EXTRA_SIZE_LIMIT,100L*1024*1024);i.putExtra(MediaStore.EXTRA_VIDEO_QUALITY,1);}a.startActivityForResult(i,92);}catch(Exception e){discard();fail(a.getString(R.string.capture_unavailable));}}
 public boolean result(int q,int result,Intent data){if(q!=92)return false;if(output!=null)a.revokeUriPermission(output,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if(result!=Activity.RESULT_OK){discard();return true;}if(!validName()||!file().isFile()||file().length()==0||file().length()>100L*1024*1024){discard();fail(a.getString(R.string.capture_invalid));return true;}review();return true;}
