 private void discard(){if(output!=null)try{a.revokeUriPermission(output,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}if(validName()){try{file().delete();}catch(Exception ignored){}}name="";output=null;}
